/** Public-domain excerpts. Editorial source and verification: output/android-v031/poetry.tsv. */
internal data class PoemEntry(val quote:ThemeQuote,val themes:Set<String>,val category:String,
    val phase:String,val weather:Set<String>,val months:Set<Int>) {
    fun matches(theme:String,dark:Boolean,condition:String,month:Int)=theme in themes &&
        (phase=="any" || phase==if(dark)"night" else "day") &&
        ("any" in weather || condition in weather) && (months.isEmpty() || month in months)
}
